(() => {
const c = document.getElementById('taste-crt');
const r = c.getBoundingClientRect();
const seen = new Map();
for (let y = r.top + 3; y < r.bottom - 3; y += 5) for (let x = r.left + 3; x < r.right - 3; x += 5) {
  c.dispatchEvent(new PointerEvent('pointermove', { clientX: x, clientY: y, pointerType: 'mouse', bubbles: true }));
  const tip = document.querySelector('.map-tip');
  if (!tip) continue;
  const name = tip.children[0].textContent;
  const s = seen.get(name) || { name, u: tip.children[2].textContent, xs: 0, ys: 0, n: 0 };
  s.xs += x; s.ys += y; s.n += 1; seen.set(name, s);
}
c.dispatchEvent(new PointerEvent('pointerleave', { bubbles: true }));
const rows = new Map([...document.querySelectorAll('#bank-list .bank-item')].map((e) => {
  const b = e.querySelector('.bi-u b');
  return [e.querySelector('.bi-name')?.textContent.trim(), { pct: e.querySelector('.bi-pct')?.textContent, unc: b ? parseFloat(b.style.width) : null }];
}));
return [...seen.values()].map((s) => ({ name: s.name, u: s.u, x: Math.round(s.xs / s.n), y: Math.round(s.ys / s.n), ...(rows.get(s.name) || {}) }))
  .sort((p, q) => p.x - q.x);
})()
